python3 - <<'PY'
import sys
from rich.traceback import Traceback
from rich.console import Console

class MyCustomError(Exception):
    def __init__(self, message, notes=None):
        super().__init__(message)
        self.__notes__ = notes

def test_exception_with_notes():
    try:
        raise MyCustomError("Original error message", notes="This is an important note about the error.")
    except MyCustomError as e:
        # Capture the traceback output
        console = Console()
        tb = Traceback.from_exception(type(e), e, None)
        console.print(tb)

def test_exception_without_notes():
    try:
        raise MyCustomError("Simple error")
    except MyCustomError as e:
        # Capture the traceback output
        console = Console()
        tb = Traceback.from_exception(type(e), e, None)
        console.print(tb)

if __name__ == "__main__":
    print("--- Testing exception with notes ---")
    test_exception_with_notes()
    print("\n--- Testing exception without notes ---")
    test_exception_without_notes()
PY
